window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6c334b96de630e53"]={"versions": [{"id": "FIG-6c334b96de630e53", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell-Ausschnitt, M2-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Konfigurations- und Instanziierungsmodells für den Functional Cluster <strong>State Management (SM)</strong> der AUTOSAR Adaptive Platform im Rahmen des Execution- bzw. Machine-Manifests (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Architektur-Kontext:</strong> State Management steuert die systemweiten Betriebszustände (Machine States und Function Group States) einer Adaptive Machine. Die Klasse <code>StateManagementModuleInstantiation</code> bildet die konkrete Ausprägung des SM-Clusters auf einer Ziel-Instanz ab und aggregiert dessen Deklarationen für Zustandsanfragen, Zustandsbenachrichtigungen und Ausführungsaktionen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>StateManagementModuleInstantiation</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Konkrete Metaklasse; spezialisiert <code>NonOsModuleInstantiation</code> (erbt damit transitive Eigenschaften wie <code>Identifiable</code> und Plattform-Instanziierungsmechanismen).\n</li><li><strong>Rolle:</strong> Zentrale Instanziierungsentität des State-Management-Daemons/Prozesses innerhalb der Manifest-Konfiguration.\n</li></ul>\n</li><li><strong>Aggregierte Zielklassen (alle spezialisieren <code>Identifiable</code>):</strong>\n<ol class=\"fig-list\"><li><strong><code>StateManagementStateRequest</code> (kursiv/abstrakt):</strong>\n<ul class=\"fig-list\"><li><strong>Rolle/Kardinalität:</strong> <code>+request [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Abstrakte Basisklasse zur Modellierung eingehender Zustandswechselanforderungen (z. B. via AUTOSAR Runtime for Adaptive Applications / ara::sm von Applikationen oder anderen Functional Clustern).\n</li></ul>\n</li><li><strong><code>StateManagementStateNotification</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Rolle/Kardinalität:</strong> <code>+notification [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Modellierung ausgehender Benachrichtigungen über eingetretene Zustandsänderungen an registrierte Konsumenten (z. B. zur Aktualisierung von Applikationszuständen oder Synchronisation).\n</li></ul>\n</li><li><strong><code>StateManagementActionList</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Rolle/Kardinalität:</strong> <code>+actionItemList [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Sequenzielle oder deterministische Liste von auszuführenden Aktionen (z. B. Trigger an Execution Management zur Umschaltung von Function Groups, Diagnostic Resets, Netzwerk-/Kommunikationssteuerungen), die an bestimmte Zustandsübergänge oder Trigger gekoppelt sind.\n</li></ul>\n</li></ol>\n</li><li><strong>Metamodell-Stereotyp <code>«atpSplitable»</code>:</strong>\n<ul class=\"fig-list\"><li>Alle drei Kompositionsbeziehungen erlauben das Aufteilen der XML-Deklarationen auf mehrere physische ARXML-Dateien (Split-Model-Prinzip), welche im Generierungs- bzw. Buildprozess über den identischen Pfad aggregiert werden.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Metamodell-Mapping)</h4>\n<p class=\"fig-p\">Das statische Klassendiagramm legt die Konfigurationsbasis für folgende Laufzeitabläufe des State Management fest:</p>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Request:</strong> Eine Adaptive Application oder ein externer Input triggert via <code>ara::sm</code> (oder Feldbus/IPC) eine in <code>+request</code> modellierte <code>StateManagementStateRequest</code>.\n</li><li><strong>Evaluation &amp; Rule Engine:</strong> Die interne SM-Zustandslogik evaluiert den eingehenden Request gegen den aktuellen Systemzustand, Sicherheitsbedingungen und Abhängigkeiten.\n</li><li><strong>Aktionsausführung:</strong> Bei gültigem Übergang wird die zugehörige <code>+actionItemList</code> (<code>StateManagementActionList</code>) abgearbeitet. Hierüber werden u. a. synchrone oder asynchrone Schnittstellenaufrufe an das Execution Management (<code>ara::exec</code>) initiiert, um Prozesse zu starten, zu terminieren oder in neue FunctionGroup-Zustände zu überführen.\n</li><li><strong>Notification / Feedback:</strong> Nach erfolgreichem Zustandswechsel (oder bei Teilschritten) werden die konfigurierten <code>+notification</code> (<code>StateManagementStateNotification</code>) an überwachende Instanzen dispatched.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Werkzeugkette:</strong>\n<ul class=\"fig-list\"><li>Entwickler/Integratoren konfigurieren das Verhalten des State Management deklarativ im Manifest. Das Attribut <code>«atpSplitable»</code> erlaubt es Funktions- und Plattform-Teams, Requests, Actions und Notifications modular in getrennten ARXML-Fragmenten (z. B. pro Funktionsgruppe oder Subsystem) zu pflegen.\n</li></ul>\n</li><li><strong>Bindung an konkrete Subklassen:</strong>\n<ul class=\"fig-list\"><li>Da <code>StateManagementStateRequest</code> abstrakt ist, müssen im Manifest konkrete Subklassen (z. B. für FunctionGroupState-Requests, Process-State-Requests oder benutzerdefinierte Events) instanziiert werden.\n</li></ul>\n</li><li><strong>Code-Generierung &amp; Stack-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die Instanziierung über <code>StateManagementModuleInstantiation</code> dient den Plattform-Generatoren als Eingabe, um Dispatch-Tabellen, IPC-Endpunkte und State-Machine-Konfigurationen für den SM-Daemon der Adaptive Platform zu kompilieren.\n</li></ul>\n</li><li><strong>Trennung von Policy und Mechanism:</strong>\n<ul class=\"fig-list\"><li>Gemäß Adaptive-Architektur implementiert State Management die fahrzeugspezifische <em>Policy</em> (definiert über ActionLists und Requests), während Execution Management (<code>ara::exec</code>) den reinen <em>Mechanismus</em> zur Prozesskontrolle bereitstellt.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5246c4366c810c59", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell-Ausschnitt, M2-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Konfigurations- und Instanziierungsmodells für den Functional Cluster <strong>State Management (SM)</strong> der AUTOSAR Adaptive Platform im Rahmen des Execution- bzw. Machine-Manifests (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Architektur-Kontext:</strong> State Management steuert die systemweiten Betriebszustände (Machine States und Function Group States) einer Adaptive Machine. Die Klasse <code>StateManagementModuleInstantiation</code> bildet die konkrete Ausprägung des SM-Clusters auf einer Ziel-Instanz ab und aggregiert dessen Deklarationen für Zustandsanfragen, Zustandsbenachrichtigungen und Ausführungsaktionen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>StateManagementModuleInstantiation</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Konkrete Metaklasse; spezialisiert <code>NonOsModuleInstantiation</code> (erbt damit transitive Eigenschaften wie <code>Identifiable</code> und Plattform-Instanziierungsmechanismen).\n</li><li><strong>Rolle:</strong> Zentrale Instanziierungsentität des State-Management-Daemons/Prozesses innerhalb der Manifest-Konfiguration.\n</li></ul>\n</li><li><strong>Aggregierte Zielklassen:</strong>\n<ol class=\"fig-list\"><li><strong><code>StateManagementStateRequest</code> (kursiv/abstrakt):</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Spezialisiert <code>Identifiable</code>.\n</li><li><strong>Rolle/Kardinalität:</strong> <code>+request [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Abstrakte Basisklasse zur Modellierung eingehender Zustandswechselanforderungen (z. B. via AUTOSAR Runtime for Adaptive Applications / ara::sm von Applikationen oder anderen Functional Clustern).\n</li></ul>\n</li><li><strong><code>StateManagementStateNotification</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Spezialisiert <code>AtpClassifier</code> und <code>Identifiable</code>.\n</li><li><strong>Rolle/Kardinalität:</strong> <code>+notification [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Modellierung ausgehender Benachrichtigungen über eingetretene Zustandsänderungen an registrierte Konsumenten (z. B. zur Aktualisierung von Applikationszuständen oder Synchronisation); fungiert im Metamodell durch <code>AtpClassifier</code> als typisierende Klassifikator-Klasse für State Notifications.\n</li></ul>\n</li><li><strong><code>StateManagementActionList</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Spezialisiert <code>Identifiable</code>.\n</li><li><strong>Rolle/Kardinalität:</strong> <code>+actionItemList [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Sequenzielle oder deterministische Liste von auszuführenden Aktionen (z. B. Trigger an Execution Management zur Umschaltung von Function Groups, Diagnostic Resets, Netzwerk-/Kommunikationssteuerungen), die an bestimmte Zustandsübergänge oder Trigger gekoppelt sind.\n</li></ul>\n</li></ol>\n</li><li><strong>Metamodell-Stereotyp <code>«atpSplitable»</code>:</strong>\n<ul class=\"fig-list\"><li>Alle drei Kompositionsbeziehungen erlauben das Aufteilen der XML-Deklarationen auf mehrere physische ARXML-Dateien (Split-Model-Prinzip), welche im Generierungs- bzw. Buildprozess über den identischen Pfad aggregiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Klassendiagramm legt die Konfigurationsbasis für folgende Laufzeitabläufe des State Management fest:</p>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Request:</strong> Eine Adaptive Application oder ein externer Input triggert via <code>ara::sm</code> (oder Feldbus/IPC) eine in <code>+request</code> modellierte <code>StateManagementStateRequest</code>.\n</li><li><strong>Evaluation &amp; Rule Engine:</strong> Die interne SM-Zustandslogik evaluiert den eingehenden Request gegen den aktuellen Systemzustand, Sicherheitsbedingungen und Abhängigkeiten.\n</li><li><strong>Aktionsausführung:</strong> Bei gültigem Übergang wird die zugehörige <code>+actionItemList</code> (<code>StateManagementActionList</code>) abgearbeitet. Hierüber werden u. a. synchrone oder asynchrone Schnittstellenaufrufe an das Execution Management (<code>ara::exec</code>) initiiert, um Prozesse zu starten, zu terminieren oder in neue FunctionGroup-Zustände zu überführen.\n</li><li><strong>Notification / Feedback:</strong> Nach erfolgreichem Zustandswechsel (oder bei Teilschritten) werden die konfigurierten <code>+notification</code> (<code>StateManagementStateNotification</code>) an überwachende Instanzen dispatched.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Werkzeugkette:</strong>\n<ul class=\"fig-list\"><li>Entwickler/Integratoren konfigurieren das Verhalten des State Management deklarativ im Manifest. Das Attribut <code>«atpSplitable»</code> erlaubt es Funktions- und Plattform-Teams, Requests, Actions und Notifications modular in getrennten ARXML-Fragmenten (z. B. pro Funktionsgruppe oder Subsystem) zu pflegen.\n</li></ul>\n</li><li><strong>Bindung an konkrete Subklassen:</strong>\n<ul class=\"fig-list\"><li>Da <code>StateManagementStateRequest</code> abstrakt ist, müssen im Manifest konkrete Subklassen (z. B. für FunctionGroupState-Requests, Process-State-Requests oder benutzerdefinierte Events) instanziiert werden.\n</li></ul>\n</li><li><strong>Code-Generierung &amp; Stack-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die Instanziierung über <code>StateManagementModuleInstantiation</code> dient den Plattform-Generatoren als Eingabe, um Dispatch-Tabellen, IPC-Endpunkte und State-Machine-Konfigurationen für den SM-Daemon der Adaptive Platform zu kompilieren.\n</li></ul>\n</li><li><strong>Trennung von Policy und Mechanism:</strong>\n<ul class=\"fig-list\"><li>Gemäß Adaptive-Architektur implementiert State Management die fahrzeugspezifische <em>Policy</em> (definiert über ActionLists und Requests), während Execution Management (<code>ara::exec</code>) den reinen <em>Mechanismus</em> zur Prozesskontrolle bereitstellt.\n</li></ul>\n</li></ul>"}, {"id": "FIG-d4c679dd08ef80d4", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell-Ausschnitt, M2-Ebene).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Konfigurations- und Instanziierungsmodells für den Functional Cluster <strong>State Management (SM)</strong> der AUTOSAR Adaptive Platform im Rahmen des Execution- bzw. Machine-Manifests (<code>AUTOSAR_TPS_ManifestSpecification</code>).\n</li><li><strong>Architektur-Kontext:</strong> State Management steuert die systemweiten Betriebszustände (Machine States und Function Group States) einer Adaptive Machine. Die Klasse <code>StateManagementModuleInstantiation</code> bildet die konkrete Ausprägung des SM-Clusters auf einer Ziel-Instanz ab und aggregiert dessen Deklarationen für Zustandsanfragen, Zustandsbenachrichtigungen und Ausführungsaktionen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>StateManagementModuleInstantiation</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Konkrete Metaklasse; spezialisiert <code>NonOsModuleInstantiation</code> (erbt damit transitive Eigenschaften wie <code>Identifiable</code> und Plattform-Instanziierungsmechanismen).\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>maxActionListDuration: TimeValue [0..1]</code>: Optionale instanzweite Maximaldauer bzw. Standard-Timeout für die Ausführung von State-Management-Aktionslisten.\n</li></ul>\n</li><li><strong>Rolle:</strong> Zentrale Instanziierungsentität des State-Management-Daemons/Prozesses innerhalb der Manifest-Konfiguration.\n</li></ul>\n</li><li><strong>Aggregierte Zielklassen:</strong>\n<ol class=\"fig-list\"><li><strong><code>StateManagementStateRequest</code> (kursiv/abstrakt):</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Spezialisiert <code>Identifiable</code>.\n</li><li><strong>Rolle/Kardinalität:</strong> <code>+request [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Abstrakte Basisklasse zur Modellierung eingehender Zustandswechselanforderungen (z. B. via AUTOSAR Runtime for Adaptive Applications / ara::sm von Applikationen oder anderen Functional Clustern).\n</li></ul>\n</li><li><strong><code>StateManagementStateNotification</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Spezialisiert <code>AtpClassifier</code> und <code>Identifiable</code>.\n</li><li><strong>Rolle/Kardinalität:</strong> <code>+notification [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Modellierung ausgehender Benachrichtigungen über eingetretene Zustandsänderungen an registrierte Konsumenten (z. B. zur Aktualisierung von Applikationszuständen oder Synchronisation); fungiert im Metamodell durch <code>AtpClassifier</code> als typisierende Klassifikator-Klasse für State Notifications.\n</li></ul>\n</li><li><strong><code>StateManagementActionList</code>:</strong>\n<ul class=\"fig-list\"><li><strong>Typ:</strong> Spezialisiert <code>Identifiable</code>.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>maxActionListDuration: TimeValue [0..1]</code>: Spezifische Maximaldauer bzw. Timeout für die Ausführung der in dieser Liste definierten Aktionen (übersteuert bei Definition den instanzweiten Standardwert).\n</li></ul>\n</li><li><strong>Rolle/Kardinalität:</strong> <code>+actionItemList [0..*]</code>\n</li><li><strong>Stereotyp:</strong> <code>«atpSplitable»</code>\n</li><li><strong>Bedeutung:</strong> Sequenzielle oder deterministische Liste von auszuführenden Aktionen (z. B. Trigger an Execution Management zur Umschaltung von Function Groups, Diagnostic Resets, Netzwerk-/Kommunikationssteuerungen), die an bestimmte Zustandsübergänge oder Trigger gekoppelt sind.\n</li></ul>\n</li></ol>\n</li><li><strong>Metamodell-Stereotyp <code>«atpSplitable»</code>:</strong>\n<ul class=\"fig-list\"><li>Alle drei Kompositionsbeziehungen erlauben das Aufteilen der XML-Deklarationen auf mehrere physische ARXML-Dateien (Split-Model-Prinzip), welche im Generierungs- bzw. Buildprozess über den identischen Pfad aggregiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das statische Klassendiagramm legt die Konfigurationsbasis für folgende Laufzeitabläufe des State Management fest:</p>\n<ol class=\"fig-list\"><li><strong>Trigger &amp; Request:</strong> Eine Adaptive Application oder ein externer Input triggert via <code>ara::sm</code> (oder Feldbus/IPC) eine in <code>+request</code> modellierte <code>StateManagementStateRequest</code>.\n</li><li><strong>Evaluation &amp; Rule Engine:</strong> Die interne SM-Zustandslogik evaluiert den eingehenden Request gegen den aktuellen Systemzustand, Sicherheitsbedingungen und Abhängigkeiten.\n</li><li><strong>Aktionsausführung &amp; Zeitüberwachung:</strong> Bei gültigem Übergang wird die zugehörige <code>+actionItemList</code> (<code>StateManagementActionList</code>) abgearbeitet. Hierüber werden u. a. synchrone oder asynchrone Schnittstellenaufrufe an das Execution Management (<code>ara::exec</code>) initiiert, um Prozesse zu starten, zu terminieren oder in neue FunctionGroup-Zustände zu überführen. Falls <code>maxActionListDuration</code> definiert ist (spezifisch an der Aktionsliste oder als Default an der Modulinstanz), wird die Einhaltung dieser Ausführungsfrist überwacht.\n</li><li><strong>Notification / Feedback:</strong> Nach erfolgreichem Zustandswechsel (oder bei Teilschritten) werden die konfigurierten <code>+notification</code> (<code>StateManagementStateNotification</code>) an überwachende Instanzen dispatched.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Authoring &amp; Werkzeugkette:</strong>\n<ul class=\"fig-list\"><li>Entwickler/Integratoren konfigurieren das Verhalten des State Management deklarativ im Manifest. Das Attribut <code>«atpSplitable»</code> erlaubt es Funktions- und Plattform-Teams, Requests, Actions und Notifications modular in getrennten ARXML-Fragmenten (z. B. pro Funktionsgruppe oder Subsystem) zu pflegen.\n</li></ul>\n</li><li><strong>Laufzeit- und Timeout-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Mit <code>maxActionListDuration: TimeValue [0..1]</code> können Integratoren sowohl modulweit (<code>StateManagementModuleInstantiation</code>) als auch feingranular pro <code>StateManagementActionList</code> Obergrenzen für die Ausführungsdauer festlegen, um hängende Aktionsfolgen deterministisch zu begrenzen und das Systemzeitverhalten abzusichern.\n</li></ul>\n</li><li><strong>Bindung an konkrete Subklassen:</strong>\n<ul class=\"fig-list\"><li>Da <code>StateManagementStateRequest</code> abstrakt ist, müssen im Manifest konkrete Subklassen (z. B. für FunctionGroupState-Requests, Process-State-Requests oder benutzerdefinierte Events) instanziiert werden.\n</li></ul>\n</li><li><strong>Code-Generierung &amp; Stack-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Die Instanziierung über <code>StateManagementModuleInstantiation</code> dient den Plattform-Generatoren als Eingabe, um Dispatch-Tabellen, IPC-Endpunkte, Timeout-Schwellen und State-Machine-Konfigurationen für den SM-Daemon der Adaptive Platform zu kompilieren.\n</li></ul>\n</li><li><strong>Trennung von Policy und Mechanism:</strong>\n<ul class=\"fig-list\"><li>Gemäß Adaptive-Architektur implementiert State Management die fahrzeugspezifische <em>Policy</em> (definiert über ActionLists und Requests), während Execution Management (<code>ara::exec</code>) den reinen <em>Mechanismus</em> zur Prozesskontrolle bereitstellt.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-6c334b96de630e53", "to": "FIG-5246c4366c810c59", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>StateManagementStateNotification</code>: Generalisierung <code>AtpClassifier</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-5246c4366c810c59", "to": "FIG-d4c679dd08ef80d4", "fr": "R23-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>StateManagementModuleInstantiation</code>: Attribut <code>+ maxActionListDuration: TimeValue [0..1]</code> hinzugefügt.\n</li><li><code>StateManagementActionList</code>: Attribut <code>+ maxActionListDuration: TimeValue [0..1]</code> hinzugefügt.\n</li></ul>"}]};
